import Foundation

// The pure tuning facts — no UI, no audio, no storage behind them.
//
// Ported from src/data/tuning.js, which is GENERATED by scripts/analyzeTuning.mjs.
// That script is the source of truth for END_BASE_FREQ: if the sample recordings
// change, re-run it and copy the two values across. They must not drift between
// platforms, or the same cents offset names a different note on each.
//
// Same contract pattern as EQ_BANDS: the engine's clamp, the mixer's slider/readout
// and persistence's load-time sanitise all read here, so the three can't drift.

/// Per-end tuning bounds in cents. ±600 reaches EVERY key: no starting pitch is more
/// than a tritone from its nearest target note.
let TUNE_MIN_CENTS = -600
let TUNE_MAX_CENTS = 600

/// Measured open-stroke fundamentals in Hz (median over analysis windows, then over
/// the round-robin variants). The bayan number is its strike resonance — a nominal
/// reference rather than a clean pitch.
let END_BASE_FREQ: [String: Double] = [
    "dayan": 641.8,
    "bayan": 79.9,
]

/// Cents offset → playback rate ratio.
func centsToRate(_ cents: Int) -> Double { pow(2.0, Double(cents) / 1200.0) }

func clampCents(_ cents: Int) -> Int {
    min(max(cents, TUNE_MIN_CENTS), TUNE_MAX_CENTS)
}

private let NOTE_NAMES = [
    "C", "C♯", "D", "D♯", "E", "F", "F♯", "G", "G♯", "A", "A♯", "B",
]

/// Frequency → nearest note name plus residual cents, e.g. "E5 −12¢". The residual
/// keeps the readout honest when the drum sits between semitones, which a hand-tuned
/// drum usually does. The minus sign is U+2212, matching the web readout exactly.
func freqToNoteName(_ freq: Double) -> String {
    let n = 69.0 + 12.0 * log(freq / 440.0) / log(2.0)
    let nearest = Int(n.rounded())
    let cents = Int(((n - Double(nearest)) * 100).rounded())
    let index = ((nearest % 12) + 12) % 12
    let octave = nearest / 12 - 1
    let name = NOTE_NAMES[index] + "\(octave)"
    if cents == 0 { return name }
    let sign = cents > 0 ? "+" : "\u{2212}"
    return "\(name) \(sign)\(abs(cents))¢"
}
